export function cameraFor(r,width,height){const p=r.runners[0],at=trackPoint(TRACK.start+p.s,p.lane),ahead=trackPoint(TRACK.start+p.s+7,p.lane);const camera=new THREE.PerspectiveCamera(width/height<.8?55:50,width/Math.max(1,height),.1,280);camera.position.set(at.x-at.tx*6.7+at.nx*1.15,3.6,at.z-at.tz*6.7+at.nz*1.15);camera.lookAt(ahead.x,1.03,ahead.z);camera.updateMatrixWorld();return camera;}
